#!/usr/bin/env python3
"""Build a brand-neutral, archival response collection worksheet, WITHOUT gold answers."""
from __future__ import annotations
from pathlib import Path
import hashlib, json
ROOT=Path(__file__).resolve().parent

def build():
    entries=[]
    photos=json.loads((ROOT/'photos'/'manifest.json').read_text(encoding='utf-8'))['photos']
    for p in sorted((ROOT/'tasks').glob('ION-REAL-*.json')):
        d=json.loads(p.read_text(encoding='utf-8'))
        entries.append({'id':d['id'],'title':d['title'],'prompt':d['prompt'],'sha256':hashlib.sha256(d['prompt'].encode()).hexdigest(),'source_ids':d['source_ids'],'photos':[x['id'] for x in photos if d['id'] in x['task_ids']]})
    assert len(entries)==8
    html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ionian Sanctuary | Evidence Assessment</title><style>
:root{color-scheme:dark;--bg:#0b1419;--ink:#f4efe4;--soft:#b2bdc0;--muted:#879a9d;--card:#16242a;--line:#385159;--accent:#d6b886}
*{box-sizing:border-box}body{margin:0;font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif;background:var(--bg);color:var(--ink)}
main{max-width:1380px;margin:auto;padding:22px 30px 40px}.mast{border-bottom:1px solid var(--line);padding:9px 0 18px;margin:0 0 18px}.kicker{text-transform:uppercase;letter-spacing:.2em;color:var(--accent);font-size:11px;font-weight:700}
h1{margin:9px 0 2px;font-family:Georgia,serif;font-weight:500;font-size:clamp(28px,4vw,48px);letter-spacing:-1px}h2{font-size:19px;margin:0 0 9px;font-family:Georgia,serif;font-weight:500}p{color:var(--soft);margin:5px 0 12px}
.small{color:var(--muted);font-size:12px}.box{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:17px;min-width:0}.controls{display:flex;flex-wrap:wrap;gap:12px}.controls>*{flex:1;min-width:155px}label{display:block;margin:0 0 5px;color:#bfcbcb;font-size:12px}[hidden]{display:none!important}input,select,textarea{font:inherit;display:block;width:100%;border-radius:7px;background:#0b191e;color:#f7f2ea;border:1px solid #48626a;padding:10px 11px}textarea{font:13px/1.55 ui-monospace,Consolas,monospace;min-height:390px;resize:vertical;white-space:pre-wrap}textarea[readonly]{background:#101e22}button{background:#263d41;color:#f0f1e9;border:1px solid #577077;border-radius:7px;font-weight:650;padding:9px 12px;cursor:pointer}button.primary{background:#b89561;border-color:#d2b580;color:#132127}button:hover{filter:brightness(1.12)}button:focus-visible{outline:2px solid #e9cfaa}.bar{height:6px;background:#2a4147;border-radius:10px;overflow:hidden;margin:7px 0}.fill{height:6px;background:var(--accent);width:0}
.top{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center}.row{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.stack{display:grid;gap:17px}.cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.photo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin:12px 0 16px}.shot{margin:0;border:1px solid #466067;border-radius:10px;overflow:hidden;background:#0d1b20}.shot img{display:block;width:100%;height:175px;object-fit:cover;background:#18282f}.shot figcaption{padding:9px 11px;color:#c7cfcf;font-size:12px}.shot figcaption strong{display:block;color:#f4ede1;margin-bottom:4px}.shot a{color:#e8c998}.full{display:block;white-space:pre-wrap;word-break:break-word}.actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.tag{border:1px solid #577077;border-radius:100px;color:var(--accent);padding:2px 9px;font-size:12px}.warn{font-size:12px;color:#c5cdbf;border-left:2px solid #a88c5a;padding:8px 12px;background:#1f2929;margin:14px 0}.check{display:flex;align-items:center;gap:8px;color:#d9ded9;font-size:13px}.check input{width:auto}.progress{font-weight:700}.slots{display:flex;flex-wrap:wrap;gap:7px}.slot{border-radius:6px;border:1px solid #40575e;padding:5px 9px;font-size:12px;color:#b8c9c8}.slot.done{color:#c9e9d2;border-color:#5c8d78;background:#1b3930}.status{min-height:22px;color:#e9d0a4}.sep{border:0;border-top:1px solid var(--line);margin:17px 0}.footer{color:var(--soft);font-size:13px;margin-top:25px}
@media(max-width:950px){main{padding:15px}.cols,.top{grid-template-columns:1fr}textarea{min-height:300px}}@media print{button{display:none!important}}
</style></head><body><main>
<header class="mast"><div class="kicker">Research dossier · Numismatics · Material provenance · Historical inference</div><h1>Ionian Sanctuary</h1><p>Evidence assessment | Claros · Colophon · Lebedus · Metropolis · Notion <span class="tag">v1.3</span></p></header>
<div class="stack"><section class="box"><div class="top"><div class="controls">
<div><label for="system">Exact tested system and version (stored with the export)</label><input id="system" placeholder="Enter exact displayed identifier"></div>
<div><label for="access">Access channel (stored with the export)</label><input id="access" placeholder="Website or deployment channel"></div>
<div><label for="task">Case</label><select id="task"></select></div><div style="max-width:135px"><label for="trial">Independent trial</label><select id="trial"><option>1</option><option>2</option><option>3</option></select></div></div>
<div><div id="progress" class="progress">0 of 24</div><div class="bar"><div class="fill" id="progressFill"></div></div></div></div>
<div class="row" style="margin-top:14px"><button id="export" class="primary">Export research record</button><button id="import">Import research record</button><input id="importFile" type="file" accept="application/json,.json" hidden><button id="clear">Clear local draft</button></div>
<div id="slots" class="slots" style="margin-top:12px"></div></section>
<section class="box"><h2>Photographic exhibits</h2><p>Real, attributed archaeological photographs. These provide geographical and comparative context; none is a photograph of RPC I 2521–2525 specimens, nor proof of an individual coin's excavation provenance.</p><div id="gallery" class="photo-grid"></div><div class="small">Original JPEGs can be downloaded once using <code>GET_PHOTOS_WINDOWS.cmd</code>. If not present locally, the page displays the public originals online. Credits and licenses accompany every image.</div></section>
<div class="cols"><section class="box"><h2 id="taskTitle">Evidence packet</h2><textarea id="prompt" readonly spellcheck="false"></textarea><div class="actions"><button class="primary" id="copy">Copy complete case</button><button id="select">Select text</button></div><div class="small" id="hash"></div></section>
<section class="box"><h2>Original response record</h2><textarea id="response" spellcheck="false" placeholder="Paste the complete, unedited response from a fresh independent session."></textarea>
<div class="controls" style="margin-top:12px"><div><label for="link">Optional shareable session URL</label><input id="link" placeholder="https://..."></div></div><label class="check"><input id="attached" type="checkbox"> Relevant photographs were explicitly supplied to the tested system for this trial</label>
<div class="actions"><button class="primary" id="save">Save this trial</button><button id="next">Next blank trial</button></div><div id="savedAt" class="small"></div></section></div>
<div id="status" class="status" role="status"></div></div>
<p class="footer">Research protocol: new independent session for each trial; use the exact frozen case prompt, preserve the complete original reply, and record whether the photographs were actually provided. Copying a prompt does not transmit the photographs. The reference keys are withheld from this interface; grading takes place separately in Python.</p></main>
<script>
'use strict';
const TASKS=__TASKS__;
const PHOTOS=__PHOTOS__;
const STORAGE='ionian_arch_eval_v13_draft';
const $=id=>document.getElementById(id);
const taskMap=Object.fromEntries(TASKS.map(t=>[t.id,t]));
let state={system:'',access:'',trials:{}};
function slot(id,n){return id+'#'+n;}
function active(){return taskMap[$('task').value]};
function currentKey(){return slot($('task').value,Number($('trial').value))};
function notice(s){$('status').textContent=s};
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch(e){notice('Browser storage unavailable; export now.')}}
function load(){try{let d=JSON.parse(localStorage.getItem(STORAGE));if(d&&typeof d==='object'&&d.trials)state=d}catch(e){}}
function settings(){state.system=$('system').value.trim();state.access=$('access').value.trim();persist()}
function gallery(){let t=active();let container=$('gallery');container.replaceChildren();for(let id of t.photos){let p=PHOTOS.find(x=>x.id===id);if(!p)continue;let figure=document.createElement('figure');figure.className='shot';let a=document.createElement('a');a.href=p.source;a.target='_blank';a.rel='noopener noreferrer';let img=document.createElement('img');img.alt=p.name;img.loading='lazy';img.src='photos/'+p.filename;img.onerror=()=>{if(img.dataset.remote!=='tried'){img.dataset.remote='tried';img.src=p.url}else{img.style.height='36px';img.alt='Photograph unavailable offline — run GET_PHOTOS_WINDOWS.cmd, then reopen.'}};a.appendChild(img);figure.appendChild(a);let fig=document.createElement('figcaption');let title=document.createElement('strong');title.textContent=p.name;fig.appendChild(title);let description=document.createElement('span');description.textContent=p.caption;fig.appendChild(description);let meta=document.createElement('div');meta.textContent='Photo: '+p.author+' · '+p.license+' · '+p.date;fig.appendChild(meta);let more=document.createElement('a');more.href=p.source;more.textContent='Source and license';more.target='_blank';more.rel='noopener noreferrer';fig.appendChild(more);figure.appendChild(fig);container.appendChild(figure)}}
function progress(){let n=0;let slots=$('slots');slots.replaceChildren();for(let t of TASKS){for(let i=1;i<=3;i++){let done=!!(state.trials[slot(t.id,i)]?.raw_response?.trim());if(done)n++;let badge=document.createElement('span');badge.className='slot'+(done?' done':'');badge.textContent=t.id.slice(-2)+' · '+i;slots.appendChild(badge)}}$('progress').textContent=n+' of 24 trials recorded';$('progressFill').style.width=n/24*100+'%'}
function view(){let t=active();if(!t)return;$('taskTitle').textContent=t.id+' · '+t.title;$('prompt').value=t.prompt;$('hash').textContent='Case integrity SHA-256: '+t.sha256;let r=state.trials[currentKey()]||{};$('response').value=r.raw_response||'';$('link').value=r.share_link||'';$('attached').checked=!!r.photographs_supplied;$('savedAt').textContent=r.collected_at?'Saved '+r.collected_at:'';gallery();progress()}
async function copy(){let s=active().prompt;try{await navigator.clipboard.writeText(s);notice('Case copied. Send the photographs separately only when included in the trial protocol.')}catch(e){$('prompt').focus();$('prompt').select();notice('Press Ctrl+C to copy the selected case text.')}}
function save(){if(!$('response').value.trim())return notice('A complete original response is required.');settings();let t=active();state.trials[currentKey()]={task_id:t.id,trial:Number($('trial').value),prompt_sha256:t.sha256,raw_response:$('response').value,share_link:$('link').value.trim(),photographs_supplied:$('attached').checked,photo_ids:t.photos,collected_at:new Date().toISOString()};persist();view();notice(t.id+' trial '+$('trial').value+' saved.')}
function next(){let idx=TASKS.findIndex(x=>x.id===$('task').value)*3+Number($('trial').value)-1;for(let i=1;i<=24;i++){let index=(idx+i)%24,t=TASKS[Math.floor(index/3)],n=(index%3)+1;if(!state.trials[slot(t.id,n)]?.raw_response?.trim()){$('task').value=t.id;$('trial').value=String(n);view();return}}notice('All slots contain responses. Export the research record.')}
function exportData(){settings();let list=TASKS.flatMap(t=>[1,2,3].map(n=>state.trials[slot(t.id,n)]).filter(Boolean));let payload={format_version:'1.3',benchmark:'Ionian Sanctuary',collection_method:'manual_frozen_prompt',model_reported:state.system||'unreported',model_platform:state.access,trials_per_task:3,exported_at:new Date().toISOString(),photo_manifest:'photos/manifest.json',trials:list};let blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ionian_evidence_trials_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);notice('Research record exported: '+list.length+' unedited responses.')}
function importData(file){if(!file)return;let r=new FileReader();r.onload=()=>{try{let data=JSON.parse(r.result);if(!Array.isArray(data.trials))throw Error('Missing trials array');if(Object.keys(state.trials).length&&!confirm('Replace the existing draft?'))return;let rows={};for(let x of data.trials){if(!taskMap[x.task_id]||!Number.isInteger(x.trial)||x.trial<1||x.trial>3)continue;if(x.prompt_sha256!==taskMap[x.task_id].sha256)continue;if(typeof x.raw_response!=='string')continue;rows[slot(x.task_id,x.trial)]=x}state={system:String(data.model_reported||''),access:String(data.model_platform||''),trials:rows};$('system').value=state.system;$('access').value=state.access;persist();view();notice('Imported '+Object.keys(rows).length+' frozen-prompt records.')}catch(e){notice('Import failed: '+e.message)}};r.readAsText(file)}
function init(){load();$('system').value=state.system||'';$('access').value=state.access||'';for(let t of TASKS){let o=document.createElement('option');o.value=t.id;o.textContent=t.id+' · '+t.title;$('task').appendChild(o)}$('task').onchange=view;$('trial').onchange=view;$('system').onchange=settings;$('access').onchange=settings;$('copy').onclick=copy;$('select').onclick=()=>{$('prompt').focus();$('prompt').select();notice('Press Ctrl+C to copy.')};$('save').onclick=save;$('next').onclick=next;$('export').onclick=exportData;$('import').onclick=()=>$('importFile').click();$('importFile').onchange=e=>importData(e.target.files[0]);$('clear').onclick=()=>{if(!confirm('Clear the saved local draft? Export first.'))return;state={system:'',access:'',trials:{}};persist();$('system').value='';$('access').value='';view();notice('Local draft cleared.')};view()}
init();
</script></body></html>'''
    html=html.replace('__TASKS__',json.dumps(entries,ensure_ascii=False).replace('</','<\\/'))
    html=html.replace('__PHOTOS__',json.dumps(photos,ensure_ascii=False).replace('</','<\\/'))
    assert 'reference/answers.json' not in html
    out=ROOT/'FRONTIER_REAL_TEST.html';out.write_text(html,encoding='utf-8')
    return out
if __name__=='__main__':print(build())
